{"path":"/root/inspect_outbound_inputs.py","content":"from openpyxl import load_workbook
import pandas as pd
from pathlib import Path

files = [
    Path('/root/Manifest_Plan.xlsx'),
    Path('/root/Dock_Scan_Log.xlsx'),
    Path('/root/Outbound_Audit_Template.xlsx'),
]

for path in files:
    print('\n' + '='*100)
    print(f'FILE: {path}')
    wb = load_workbook(path, data_only=False)
    print('Sheet names:', wb.sheetnames)
    if path.name in ['Manifest_Plan.xlsx', 'Dock_Scan_Log.xlsx']:
        for s in wb.sheetnames:
            ws = wb[s]
            rows = list(ws.iter_rows(values_only=True))
            headers = list(rows[0]) if rows else []
            print(f'\nSheet: {s}')
            print('Headers:', headers)
            print('First 5 rows:')
            for row in rows[1:6]:
                print(list(row))
            # also print pandas view for exact df columns
            try:
                df = pd.read_excel(path, sheet_name=s)
                print('Pandas columns:', list(df.columns))
                print(df.head(5).to_string(index=False))
            except Exception as e:
                print('Pandas read error:', e)
    else:
        for s in wb.sheetnames:
            ws = wb[s]
            rows = list(ws.iter_rows(values_only=True))
            if s == 'Overview':
                print('\nOverview full contents:')
                if not rows:
                    print('(empty)')
                for i, row in enumerate(rows, start=1):
                    print(f'Row {i}: {list(row)}')
            else:
                headers = list(rows[0]) if rows else []
                print(f'\nSheet: {s}')
                print('Headers:', headers)
